  emulate,
  enableNetworkThrottling,
  clearAllNetworkEmulation,
  enableCPUThrottling,
  disableCPUThrottling,
  goOffline,
  MOBILE_USERAGENT: MOTOG4_USERAGENT,
  DESKTOP_USERAGENT,
};

